import json
from src.nodes.base import BaseNode
from src.runtime.procedural_scene_assembler import get_procedural_scene_assembler
from src.runtime.scene_realization_review import get_scene_realization_review
from src.runtime import houdini_runtime
from src.runtime.transaction_manager import get_transaction_manager
from src.runtime.scene_cache import get_scene_cache


class HouMCPSceneRealizeNode(BaseNode):
    name = "hou_mcp_scene_realize"
    category = "Houdini"

    def __init__(self):
        super().__init__()
        self.icon_path = "icons/houdini_icon.png"
        # [AUTO-GENERATED-PORTS-START]
        self.add_input("layout_plan_json", "string", widget_type="text", default="{}")
        self.add_input("staging_plan_json", "string", widget_type="text", default="{}")
        self.add_input("dry_run", "bool", widget_type="bool", default=False)
        self.add_input("rollback_on_error", "bool", widget_type="bool", default=True)
        self.add_output("assembly_id", "string")
        self.add_output("operations_executed", "list")
        self.add_output("status", "string")
        self.add_output("graph_diff", "any")
        self.add_output("realization_review", "any")
        self.add_output("report_json", "string")
        # [AUTO-GENERATED-PORTS-END]

    def _empty_report(self, error=""):
        empty_diff = {"created": [], "deleted": [], "modified": [], "cooked": [], "connections_changed": [], "flags_changed": []}
        report = {"assembly_id": "", "status": "failed", "operations_executed": [], "errors": [error] if error else [], "graph_diff": empty_diff, "realization_review": {}}
        return {"assembly_id": "", "operations_executed": [], "status": "failed", "graph_diff": empty_diff, "realization_review": {}, "report_json": json.dumps(report, indent=2, default=str), "exec_out": True}

    async def execute(self, inputs):
        raw_layout = (inputs.get("layout_plan_json") or "{}").strip() or "{}"
        raw_staging = (inputs.get("staging_plan_json") or "{}").strip() or "{}"
        dry_run = bool(inputs.get("dry_run", False))
        rollback_on_error = bool(inputs.get("rollback_on_error", True))

        try:
            layout_plan = json.loads(raw_layout) if isinstance(raw_layout, str) else raw_layout
        except json.JSONDecodeError as exc:
            self.log_error(f"layout_plan_json is not valid JSON: {exc}")
            return self._empty_report(error=f"invalid layout_plan_json: {exc}")

        try:
            staging_plan = json.loads(raw_staging) if isinstance(raw_staging, str) else raw_staging
        except json.JSONDecodeError as exc:
            self.log_error(f"staging_plan_json is not valid JSON: {exc}")
            return self._empty_report(error=f"invalid staging_plan_json: {exc}")

        if not isinstance(layout_plan, dict) or not isinstance(staging_plan, dict):
            self.log_error("layout_plan_json and staging_plan_json must be JSON objects.")
            return self._empty_report(error="inputs must be JSON objects")

        assembler = get_procedural_scene_assembler()
        try:
            assembly = assembler.assemble_scene(layout_plan, staging_plan)
        except Exception as exc:
            self.log_error(f"Scene assembly failed: {exc}")
            return self._empty_report(error=f"assembly failed: {exc}")

        operations = assembly.get("operations", [])
        assembly_id = assembly.get("assembly_id", "")

        if dry_run:
            self.log_info(f"dry_run: {len(operations)} scene operations generated, no execution.")
            empty_diff = {"created": [], "deleted": [], "modified": [], "cooked": [], "connections_changed": [], "flags_changed": []}
            report = {"assembly_id": assembly_id, "status": "validated", "operations_executed": [], "errors": [], "graph_diff": empty_diff, "realization_review": {}, "phase_counts": assembly.get("phase_counts", {}), "total_ops": assembly.get("total_ops", 0)}
            return {"assembly_id": assembly_id, "operations_executed": [], "status": "validated", "graph_diff": empty_diff, "realization_review": {}, "report_json": json.dumps(report, indent=2, default=str), "exec_out": True}

        validation_errors = []
        for i, op in enumerate(operations):
            err = houdini_runtime._validate_operation(op)
            if err:
                validation_errors.append({"index": i, "error": err})
        if validation_errors:
            self.log_error(f"Scene operation validation failed: {len(validation_errors)} error(s).")
            empty_diff = {"created": [], "deleted": [], "modified": [], "cooked": [], "connections_changed": [], "flags_changed": []}
            report = {"assembly_id": assembly_id, "status": "failed", "operations_executed": [], "errors": validation_errors, "graph_diff": empty_diff, "realization_review": {}}
            return {"assembly_id": assembly_id, "operations_executed": [], "status": "failed", "graph_diff": empty_diff, "realization_review": {}, "report_json": json.dumps(report, indent=2, default=str), "exec_out": True}

        mgr = get_transaction_manager()
        cache = get_scene_cache()
        cache.clear_dirty_state()

        try:
            txn_id = await mgr.begin_transaction(f"scene_realize_{assembly_id[:8]}", metadata={"assembly_id": assembly_id, "op_count": len(operations)})
        except Exception as exc:
            self.log_error(f"begin_transaction failed: {exc}")
            return self._empty_report(error=f"begin failed: {exc}")

        executed = []
        first_error = None

        for i, op in enumerate(operations):
            recorded = await houdini_runtime.execute_operation(op)
            try:
                await mgr.record_operation(txn_id, recorded)
            except Exception as exc:
                first_error = f"record_operation failed at index {i}: {exc}"
                self.log_error(first_error)
                break
            executed.append({"index": i, "op": recorded.get("op"), "status": recorded.get("status")})
            if recorded.get("status") == "failed":
                first_error = recorded.get("error") or f"op '{recorded.get('op')}' failed"
                self.log_error(f"Operation {i} ({recorded.get('op')}) failed: {first_error}")
                break

        rollback_performed = False
        if first_error is not None:
            if rollback_on_error:
                self.log_info(f"Rolling back scene realization '{txn_id}'...")
                try:
                    await mgr.rollback_transaction(txn_id)
                    rollback_performed = True
                except Exception as exc:
                    try:
                        await mgr.mark_failed(txn_id, str(exc))
                    except Exception:
                        pass
            else:
                try:
                    await mgr.mark_failed(txn_id, first_error)
                except Exception:
                    pass
        else:
            try:
                await mgr.commit_transaction(txn_id)
            except Exception as exc:
                self.log_error(f"commit_transaction failed: {exc}")

        final = await mgr.get_transaction(txn_id) or {}
        diff = cache.get_dirty_nodes()
        status = final.get("status", "pending")

        path_map = {}
        for rec_op in (final.get("operations") or []):
            if rec_op.get("op") == "create_node" and rec_op.get("status") == "ok":
                result = rec_op.get("result") or {}
                path = result.get("path", "")
                name_val = result.get("name", "")
                if path and name_val:
                    path_map[name_val] = path

        assembly_result = {"zone_map": {}, "path_map": path_map, "phase_counts": assembly.get("phase_counts", {}), "staging_plan": staging_plan}

        review = {}
        try:
            reviewer = get_scene_realization_review()
            review = reviewer.generate_realization_review(assembly_result, layout_plan)
        except Exception as exc:
            self.log_warning(f"Scene review failed (non-critical): {exc}")

        if status == "committed":
            score = review.get("overall_score", 0.0)
            self.log_success(f"Scene realization committed ({len(executed)} ops). Review score: {score:.2f}")
        elif status == "rolled_back":
            self.log_info("Scene realization rolled back.")
        elif status == "failed":
            self.log_error("Scene realization failed (no rollback performed).")

        all_errors = list(final.get("errors") or [])
        report = {"assembly_id": assembly_id, "transaction_id": txn_id, "status": status, "operations_executed": executed, "rollback_performed": rollback_performed, "errors": all_errors, "graph_diff": diff, "realization_review": review, "phase_counts": assembly.get("phase_counts", {}), "total_ops": assembly.get("total_ops", 0)}
        return {"assembly_id": assembly_id, "operations_executed": executed, "status": status, "graph_diff": diff, "realization_review": review, "report_json": json.dumps(report, indent=2, default=str), "exec_out": True}


def register_node():
    return HouMCPSceneRealizeNode
